(176496, 10080, 1647, '<td valign="top">Nice photo, my only criticisms relate to slightly uneven light on the top-left coin and some coins are ever so slightly rotated.  A very powerful image otherwise.</td>', 'Nice photo, my only criticisms relate to slightly uneven light on the top-left coin and some coins are ever so slightly rotated.  A very powerful image otherwise.', '2002-12-23 00:14:50.000000', NULL, 1),
(176503, 9992, 1647, '<td valign="top">Great focus on the tower and the framing is very good, however the out of focus grass/branches (?) in the foreground are a little off-putting.</td>', 'Great focus on the tower and the framing is very good, however the out of focus grass/branches (?) in the foreground are a little off-putting.', '2002-12-23 00:16:30.000000', NULL, 1),
(176504, 9964, 3936, '<td valign="top">Nice creative take on four.  Would have liked it a bit brighter.  Good depth of field.</td>', 'Nice creative take on four.  Would have liked it a bit brighter.  Good depth of field.', '2002-12-23 00:16:41.000000', NULL, 1),
(176509, 9925, 3936, '<td valign="top">If the apparent movement is real, then just wondering how many times you had to try until you got this one.  Very creative. 9</td>', 'If the apparent movement is real, then just wondering how many times you had to try until you got this one.  Very creative. 9', '2002-12-23 00:18:50.000000', NULL, 1),
(176511, 9904, 1647, '<td valign="top">A powerful photo although the shallow DOF sends my attention to the flag rather than the tombstones - which is not what I expected in the "four" challenge.</td>', 'A powerful photo although the shallow DOF sends my attention to the flag rather than the tombstones - which is not what I expected in the "four" challenge.', '2002-12-23 00:19:32.000000', NULL, 1),
(176512, 10016, 1647, '<td valign="top">Nice colours, nice poses.  The only distracting element is the shadow (especially on the white background), although you still get a good score from me.</td>', 'Nice colours, nice poses.  The only distracting element is the shadow (especially on the white background), although you still get a good score from me.', '2002-12-23 00:21:48.000000', NULL, 1),
(176513, 10036, 3936, '<td valign="top">Good composition, nice color, a bit dark.  Would have liked it brighter with more contrast for more pop.  Very good depth of field.  7</td>', 'Good composition, nice color, a bit dark.  Would have liked it brighter with more contrast for more pop.  Very good depth of field.  7', '2002-12-23 00:22:00.000000', NULL, 1),
(176514, 10027, 5212, '<td valign="top">Would love to know how you did this, gave it a 9!</td>', 'Would love to know how you did this, gave it a 9!', '2002-12-23 00:22:10.000000', NULL, 1),
(176516, 10039, 1647, '<td valign="top">That must be a clean mirror...  Either that or I''m misunderstanding how this was achieved.  Good work.</td>', 'That must be a clean mirror...  Either that or I''m misunderstanding how this was achieved.  Good work.', '2002-12-23 00:23:20.000000', NULL, 1),
(176518, 10011, 5212, '<td valign="top">I might have liked more depth of field here, (although I bet you did this on purpose), otherwise great photo.</td>', 'I might have liked more depth of field here, (although I bet you did this on purpose), otherwise great photo.', '2002-12-23 00:23:27.000000', NULL, 1),
(176519, 9871, 772, '<td valign="top">focus here is a bit too soft... - setzler</td>', 'focus here is a bit too soft... - setzler', '2002-12-23 00:23:47.000000', NULL, 1),
(176520, 10056, 5212, '<td valign="top">Nice use of color.</td>', 'Nice use of color.', '2002-12-23 00:24:02.000000', NULL, 1),
(176521, 10047, 3936, '<td valign="top">Good lighting, good composition, good contrast.  Would like to have seen sharper focus.  7</td>', 'Good lighting, good composition, good contrast.  Would like to have seen sharper focus.  7', '2002-12-23 00:24:18.000000', NULL, 1),
