(176626, 9964, 4648, '<td valign="top">I love this.  I love the tone.  Really sets this off.  Great job.  It''s a wonderful compotiion with great execution.  A 10 all day long.  PTL</td>', 'I love this.  I love the tone.  Really sets this off.  Great job.  It''s a wonderful compotiion with great execution.  A 10 all day long.  PTL', '2002-12-23 01:26:21.000000', NULL, 1),
(176628, 9897, 4648, '<td valign="top">This is too cute, too cool, too creative, and too well done.  But it makes me want to give you a 4, instead of the 8 I want to give you.  PTL</td>', 'This is too cute, too cool, too creative, and too well done.  But it makes me want to give you a 4, instead of the 8 I want to give you.  PTL', '2002-12-23 01:28:43.000000', NULL, 1),
