(178315, 9832, 3294, '<td valign="top">Mmm!  I can smell ''em from here!  Candles are so hard to shoot... correct exposure is tough.</td>', 'Mmm!  I can smell ''em from here!  Candles are so hard to shoot... correct exposure is tough.', '2002-12-26 12:05:49.000000', NULL, 1),
(178316, 9830, 3294, '<td valign="top">I think the reflections detract from the photo.  The eyes are drawn to it and it looks like the top two mints are underexposed.  Not sure how I would do it different.</td>', 'I think the reflections detract from the photo.  The eyes are drawn to it and it looks like the top two mints are underexposed.  Not sure how I would do it different.', '2002-12-26 12:06:59.000000', NULL, 1),
(178319, 9889, 3294, '<td valign="top">Very cool!   How many people are mentioning the backdrop needs to be ironed?  hehe  Very clever concept and unique in the challenge.</td>', 'Very cool!   How many people are mentioning the backdrop needs to be ironed?  hehe  Very clever concept and unique in the challenge.', '2002-12-26 12:08:28.000000', NULL, 1),
(178321, 9946, 3294, '<td valign="top">Nice photo, although I have a hard time reading the text.</td>', 'Nice photo, although I have a hard time reading the text.', '2002-12-26 12:09:15.000000', NULL, 1),
(178323, 9945, 3575, '<td valign="top">IMHO, if you centered your object in the frame and rotated it clockwise a little to correct the tilt it would be better.</td>', 'IMHO, if you centered your object in the frame and rotated it clockwise a little to correct the tilt it would be better.', '2002-12-26 12:10:29.000000', NULL, 1),
(178324, 9937, 3294, '<td valign="top">Nice colors and good lighting.  I like the exposure too. (8)</td>', 'Nice colors and good lighting.  I like the exposure too. (8)', '2002-12-26 12:10:33.000000', NULL, 1),
(178325, 9886, 3575, '<td valign="top">Wondeful lighting and composition. Very nice.</td>', 'Wondeful lighting and composition. Very nice.', '2002-12-26 12:10:54.000000', NULL, 1),
(178329, 9963, 3575, '<td valign="top">Beautiful house. I think it''s tilting a little to the right but the color saturation is great.</td>', 'Beautiful house. I think it''s tilting a little to the right but the color saturation is great.', '2002-12-26 12:13:57.000000', NULL, 1),
(178331, 10050, 3575, '<td valign="top">Beautiful photo. The lighting and composition is great and I love the bg color. But, what does this have to do with four? I''ve totally missed it.</td>', 'Beautiful photo. The lighting and composition is great and I love the bg color. But, what does this have to do with four? I''ve totally missed it.', '2002-12-26 12:15:08.000000', NULL, 1),
(178333, 9947, 3575, '<td valign="top">Maybe more light and more DOF, you have two pieces and the one in back, being part of your subject, needs a little more focus.</td>', 'Maybe more light and more DOF, you have two pieces and the one in back, being part of your subject, needs a little more focus.', '2002-12-26 12:16:24.000000', NULL, 1),
