INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(178653, 9944, 173, '<td valign="top">Great idea, but as I am sure you have already heard, more light. I bet this was a tough shot to get. Good job overall.</td>', 'Great idea, but as I am sure you have already heard, more light. I bet this was a tough shot to get. Good job overall.', '2002-12-27 11:37:25.000000', NULL, 1),
(178654, 9877, 173, '<td valign="top">Not sure what you are going for in this shot. Cropping, light, and composition are all great, but it is difficult to see how it fits the challenge. (Maybe it is too obvious and I am trying too hard.)</td>', 'Not sure what you are going for in this shot. Cropping, light, and composition are all great, but it is difficult to see how it fits the challenge. (Maybe it is too obvious and I am trying too hard.)', '2002-12-27 11:40:18.000000', NULL, 1),
